// dec2bin.cpp - Decimal to binary
#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    cout << "Enter a decimal number: ";
    cin >> n;

    if (n == 0) {
        cout << "Binary: 0" << endl;
        return 0;
    }

    string binary = "";
    int temp = n;
    while (temp > 0) {
        int rem = temp % 2;                // remainder is the next bit
        binary = char('0' + rem) + binary; // add the bit on the left
        temp = temp / 2;
    }
    cout << "Binary of " << n << " = " << binary << endl;
    return 0;
}

// bin2dec.cpp - Binary to decimal
#include <iostream>
#include <string>
using namespace std;

int main() {
    string bin;
    cout << "Enter a binary number: ";
    cin >> bin;

    int decimal = 0;
    for (int i = 0; i < (int)bin.length(); i++) {
        decimal = decimal * 2 + (bin[i] - '0');
    }
    cout << "Decimal = " << decimal << endl;
    return 0;
}

// anybase.cpp - Decimal to any base (2 to 16)
#include <iostream>
#include <string>
using namespace std;

int main() {
    int n, base;
    string digits = "0123456789ABCDEF";

    cout << "Enter a decimal number: ";
    cin >> n;
    cout << "Enter the base (2, 8 or 16): ";
    cin >> base;

    string result = "";
    if (n == 0) result = "0";
    while (n > 0) {
        result = digits[n % base] + result;
        n = n / base;
    }
    cout << "Result = " << result << endl;
    return 0;
}

