// menuconvert.cpp - Menu-driven base converter
#include <iostream>
#include <string>
using namespace std;

int main() {
    int n, choice, base;
    string digits = "0123456789ABCDEF";

    cout << "Enter a decimal number: ";
    cin >> n;
    cout << "1. Binary\n2. Octal\n3. Hexadecimal\nEnter choice: ";
    cin >> choice;

    switch (choice) {
        case 1: base = 2;  break;
        case 2: base = 8;  break;
        case 3: base = 16; break;
        default:
            cout << "Invalid choice" << endl;
            return 0;
    }

    string result = (n == 0) ? "0" : "";
    while (n > 0) {
        result = digits[n % base] + result;
        n /= base;
    }
    cout << "Answer = " << result << endl;
    return 0;
}
